# -*- coding: utf-8 -*-
import sys
import os
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

from baserequest import BaseRequest
# ============ MT4 ORDER TYPES (Replaces OANDA) ============

class OrderType:
    """MT4 Order Types"""
    LIMIT = "LIMIT"
    MARKET = "MARKET"
    STOP = "STOP"
    STOP_LIMIT = "STOP_LIMIT"


class TimeInForce:
    """Time in Force"""
    GTC = "GTC"  # Good Till Cancelled
    DAY = "DAY"  # Day order
    IOC = "IOC"  # Immediate or Cancel
    FOK = "FOK"  # Fill or Kill


class OrderPositionFill:
    """Position Fill Types"""
    DEFAULT = "DEFAULT"
    OPEN_ONLY = "OPEN_ONLY"
    REDUCE_FIRST = "REDUCE_FIRST"
    REDUCE_ONLY = "REDUCE_ONLY"


class Units:
    """Units wrapper"""
    def __init__(self, units):
        self.value = str(units)


class PriceValue:
    """Price value wrapper"""
    def __init__(self, price):
        self.value = str(price)


class LimitOrderRequest(BaseRequest):
    """create a LimitOrderRequest.

    LimitOrderRequest is used to build the body for a LimitOrder.
    The body can be used to pass to the OrderCreate endpoint.
    
    NOTE: This has been adapted from OANDA to support MT4 order structure.
    For MT4, actual order execution is handled via the file bridge.
    This class now serves as a data structure for order parameters.
    """

    def __init__(self,
                 instrument,
                 units,
                 price,
                 positionFill=OrderPositionFill.DEFAULT,
                 clientExtensions=None,
                 takeProfitOnFill=None,
                 timeInForce=TimeInForce.GTC,
                 gtdTime=None,
                 stopLossOnFill=None,
                 trailingStopLossOnFill=None,
                 tradeClientExtensions=None):
        """
        Instantiate a LimitOrderRequest.

        Parameters
        ----------

        instrument : string (required)
            the instrument to create the order for (e.g., 'EURUSD' for MT4)

        units: integer (required)
            the number of units. If positive the order results in a LONG
            order. If negative the order results in a SHORT order

        price: float (required)
            the price indicating the limit.

        Example
        -------

        >>> from mt4_order_requests import LimitOrderRequest
        >>> 
        >>> # Create a limit order request (for MT4)
        >>> order = LimitOrderRequest(
        ...     instrument="EURUSD",
        ...     units=10000,
        ...     price=1.0950,
        ...     stopLossOnFill=1.0900,
        ...     takeProfitOnFill=1.1000
        ... )
        >>> 
        >>> # For actual MT4 execution, use the MT4 client:
        >>> from mt4_price_provider import get_mt4_prices
        >>> mt4 = get_mt4_prices()
        >>> result = mt4.buy("EURUSD", 0.01, 1.0900, 1.1000)
        """
        super(LimitOrderRequest, self).__init__()

        # by default for a LIMIT order
        self._data.update({"type": OrderType.LIMIT})
        self._data.update({"timeInForce": timeInForce})

        # required
        self._data.update({"instrument": instrument})
        self._data.update({"units": Units(units).value})
        self._data.update({"price": PriceValue(price).value})

        # optional, but required if timeInForce.GTD
        self._data.update({"gtdTime": gtdTime})
        if timeInForce == TimeInForce.GTD and not gtdTime:
            raise ValueError("gtdTime missing")

        # optional
        self._data.update({"positionFill": positionFill})
        self._data.update({"clientExtensions": clientExtensions})
        self._data.update({"takeProfitOnFill": takeProfitOnFill})
        self._data.update({"stopLossOnFill": stopLossOnFill})
        self._data.update({"trailingStopLossOnFill": trailingStopLossOnFill})
        self._data.update({"tradeClientExtensions": tradeClientExtensions})

    @property
    def data(self):
        """data property.

        return the JSON order body
        """
        return dict({"order": super(LimitOrderRequest, self).data})


# ============ MT4 Order Execution Helper ============

class MT4OrderExecutor:
    """
    Helper class to execute orders in MT4 (replaces OANDA execution)
    """
    
    def __init__(self):
        from mt4_price_provider import get_mt4_prices
        self.mt4 = get_mt4_prices()
    
    def execute_limit_order(self, instrument, units, price, stop_loss=None, take_profit=None):
        """
        Execute a limit order in MT4
        
        Note: MT4 limit orders are handled via market orders with price limits
        """
        try:
            # Convert units to MT4 volume (standard lots)
            volume = abs(int(units)) / 100000
            
            if units > 0:
                # BUY order
                result = self.mt4.buy(instrument, volume, stop_loss, take_profit)
            else:
                # SELL order
                result = self.mt4.sell(instrument, volume, stop_loss, take_profit)
            
            return result
        except Exception as e:
            return {'success': False, 'error': str(e)}
    
    def execute_market_order(self, instrument, units, stop_loss=None, take_profit=None):
        """Execute a market order in MT4"""
        volume = abs(int(units)) / 100000
        
        if units > 0:
            return self.mt4.buy(instrument, volume, stop_loss, take_profit)
        else:
            return self.mt4.sell(instrument, volume, stop_loss, take_profit)


# ============ Market Order Request (MT4 Equivalent) ============

class MarketOrderRequest(BaseRequest):
    """Market Order Request for MT4 (replaces OANDA market orders)"""
    
    def __init__(self,
                 instrument,
                 units,
                 stopLossOnFill=None,
                 takeProfitOnFill=None,
                 comment="MT4_Trade"):
        """
        Instantiate a MarketOrderRequest.
        
        Parameters
        ----------
        instrument : string
            the instrument to trade (e.g., 'EURUSD')
        units : integer
            positive for BUY, negative for SELL
        stopLossOnFill : float, optional
            stop loss price
        takeProfitOnFill : float, optional
            take profit price
        comment : string, optional
            order comment
        """
        super(MarketOrderRequest, self).__init__()
        
        self._data.update({"type": OrderType.MARKET})
        self._data.update({"instrument": instrument})
        self._data.update({"units": Units(units).value})
        
        if stopLossOnFill:
            self._data.update({"stopLossOnFill": stopLossOnFill})
        if takeProfitOnFill:
            self._data.update({"takeProfitOnFill": takeProfitOnFill})
        if comment:
            self._data.update({"comment": comment})
    
    @property
    def data(self):
        return dict({"order": super(MarketOrderRequest, self).data})
